export function getAllHsCodes(): HsCodeEntry[] {
  return HS_CODE_DATABASE;
}

export function getHsCodesBySection(section: number): HsCodeEntry[] {
  return HS_CODE_DATABASE.filter((e) => e.section === section);
}

export function getHsCodesByChapter(chapter: number): HsCodeEntry[] {
  return HS_CODE_DATABASE.filter((e) => e.chapter === chapter);
}

export function getHsCodesByCategory(category: string): HsCodeEntry[] {
  return HS_CODE_DATABASE.filter((e) => e.category === category);
}

export function getAllCategories(): string[] {
  return Array.from(new Set(HS_CODE_DATABASE.map((e) => e.category))).sort();
}

export function getAllChapters(): { chapter: number; section: number; category: string }[] {
  const seen = new Map<number, { chapter: number; section: number; category: string }>();
  for (const e of HS_CODE_DATABASE) {
    if (!seen.has(e.chapter)) seen.set(e.chapter, { chapter: e.chapter, section: e.section, category: e.category });
  }
  return Array.from(seen.values()).sort((a, b) => a.chapter - b.chapter);
}
